style.css:
/* Change background color of the body */
body {
    background-color: #1a1a1a !important;
    color: #f0f0f0 !important;
}

/* Customize links */
a {
    property: value;
    color: #4da6ff !important;
}

/* Style a specific header or bar */
header {
    background-color: #000000 !important;
}
